    b_chan_t b;
    logic<1> b_valid;
    logic<1> ar_ready;
    r_chan_t r;
    logic<1> r_valid;
@PACKED@};

struct aw_chan_t {
    logic<(uint64_t)(((uint64_t)(ADDR_WIDTH) & ((1ull << 32) - 1ull)))> addr;
    axi_pkg::prot_t prot;
@PACKED@};

struct w_chan_t {
    logic<(uint64_t)(((uint64_t)(DATA_WIDTH) & ((1ull << 32) - 1ull)))> data;
    logic<(uint64_t)(((uint64_t)(DATA_WIDTH) & ((1ull << 32) - 1ull)) / ((uint64_t)(8) & ((1ull << 32) - 1ull)))> strb;
@PACKED@};

struct ar_chan_t {
    logic<(uint64_t)(((uint64_t)(ADDR_WIDTH) & ((1ull << 32) - 1ull)))> addr;
    axi_pkg::prot_t prot;
@PACKED@};

struct r_chan_t {
    logic<(uint64_t)(((uint64_t)(DATA_WIDTH) & ((1ull << 32) - 1ull)))> data;
    axi_pkg::resp_t resp;
@PACKED@};

struct req_t {
    aw_chan_t aw;
    logic<1> aw_valid;
    w_chan_t w;
    logic<1> w_valid;
    logic<1> b_ready;
    ar_chan_t ar;
    logic<1> ar_valid;
    logic<1> r_ready;
@PACKED@};

struct resp_t {
    logic<1> aw_ready;
    logic<1> w_ready;
    b_chan_t b;
    logic<1> b_valid;
    logic<1> ar_ready;
    r_chan_t r;
    logic<1> r_valid;
@PACKED@};
